/* (00|30): 35 VRR nodes, 10 targets */
int jkg_0030(double *out, const size_t *st, const int *pos, const GPair *B, int bs,
                const GPair *K, int ks, double cut, double fac, const double *tab, double *wk)
{
        const int nb = B->n, nk = K->n, ncb = B->nc, nck = K->nc;
        const double *pax = bs ? B->rjx : B->rix, *pay = bs ? B->rjy : B->riy, *paz = bs ? B->rjz : B->riz;
        const double *qcx = ks ? K->rjx : K->rix, *qcy = ks ? K->rjy : K->riy, *qcz = ks ? K->rjz : K->riz;
        double *v = wk, *w = v + (size_t)10 * nb, *SK = w + (size_t)10 * ncb;
        double *FT = SK + (size_t)nck * ncb * 10;     /* F_m of the bra primitives, FT[m * nb + b] */
        int t, b, cb, kc, i, any = 0;
        memset(SK, 0, sizeof(double) * nck * ncb * 10);
        for (t = 0; t < nk; t++) {
                if (K->bnd[t] < cut) continue;
                any = 1;
                const int nbt = n_above(B->beta, nb, cut * B->bmax / K->bnd[t]);
                const double q = K->p[t], qx = K->px[t], qy = K->py[t], qz = K->pz[t];
                const double QCx = qcx[t], QCy = qcy[t], QCz = qcz[t];
                const double h2q = .5 / q;
                (void)QCx; (void)QCy; (void)QCz; (void)h2q;
#pragma omp simd
                for (b = 0; b < nbt; b++) {
                        const double p = B->p[b], s = 1. / (p + q);
                        const double dx = B->px[b] - qx, dy = B->py[b] - qy, dz = B->pz[b] - qz;
                        const double T = p * q * s * (dx * dx + dy * dy + dz * dz);
                        const int inr = T < GT_TMAX;
                        const int k = inr ? (int)(T * (1. / GT_STEP) + .5) : 0;
                        const int o = k * GT_TN;
                        const double dt = inr ? k * GT_STEP - T : 0;
                        const double Ta = inr ? GT_TMAX : T, h = .5 / Ta;
                        const double a0 = .886226925452758014 / sqrt(Ta);
                        const double a1 = a0 * (1 * h);
                        const double a2 = a1 * (3 * h);
                        const double a3 = a2 * (5 * h);
                        const double f3 = tab[o + 3] + dt * (1. / 1) * (tab[o + 4] + dt * (1. / 2) * (tab[o + 5] + dt * (1. / 3) * (tab[o + 6] + dt * (1. / 4) * (tab[o + 7] + dt * (1. / 5) * (tab[o + 8] + dt * (1. / 6) * (tab[o + 9]))))));
                        const double ex = tab[GT_N * GT_TN + k] * (1 + dt * (1 + dt * (1. / 2) * (1 + dt * (1. / 3) * (1 + dt * (1. / 4) * (1 + dt * (1. / 5) * (1 + dt * (1. / 6)))))));
                        const double T2 = 2 * T;
                        const double f2 = (T2 * f3 + ex) * (1. / 5);
                        const double f1 = (T2 * f2 + ex) * (1. / 3);
                        const double f0 = (T2 * f1 + ex) * (1. / 1);
                        const double F0 = inr ? f0 : a0;
                        const double F1 = inr ? f1 : a1;
                        const double F2 = inr ? f2 : a2;
                        const double F3 = inr ? f3 : a3;
                        FT[0 * nb + b] = F0;
                        FT[1 * nb + b] = F1;
                        FT[2 * nb + b] = F2;
                        FT[3 * nb + b] = F3;
                }
#pragma omp simd
                for (b = 0; b < nbt; b++) {
                        const double p = B->p[b], s = 1. / (p + q);
                        const double dx = B->px[b] - qx, dy = B->py[b] - qy, dz = B->pz[b] - qz;
                        const double rho = p * q * s;
                        const double F0 = FT[0 * nb + b];
                        const double F1 = FT[1 * nb + b];
                        const double F2 = FT[2 * nb + b];
                        const double F3 = FT[3 * nb + b];
                        const double PAx = pax[b], PAy = pay[b], PAz = paz[b];
                        const double WPx = -q * s * dx, WPy = -q * s * dy, WPz = -q * s * dz;
                        const double WQx = p * s * dx, WQy = p * s * dy, WQz = p * s * dz;
                        const double h2p = .5 / p, rp = rho / p, rq = rho / q, h2pq = .5 * s;
                        (void)PAx; (void)PAy; (void)PAz; (void)WPx; (void)WPy; (void)WPz;
                        (void)WQx; (void)WQy; (void)WQz; (void)h2p; (void)rp; (void)rq; (void)h2pq;
                        const double g = B->kp[b] * sqrt(s);
                        const double x000_000_0 = F0;
                        const double x000_000_1 = F1;
                        const double x000_100_0 = QCx * x000_000_0 + WQx * x000_000_1;
                        const double x000_000_2 = F2;
                        const double x000_100_1 = QCx * x000_000_1 + WQx * x000_000_2;
                        const double x000_200_0 = QCx * x000_100_0 + WQx * x000_100_1 + 1 * h2q * (x000_000_0 - rq * x000_000_1);
                        const double x000_000_3 = F3;
                        const double x000_100_2 = QCx * x000_000_2 + WQx * x000_000_3;
                        const double x000_200_1 = QCx * x000_100_1 + WQx * x000_100_2 + 1 * h2q * (x000_000_1 - rq * x000_000_2);
                        const double x000_300_0 = QCx * x000_200_0 + WQx * x000_200_1 + 2 * h2q * (x000_100_0 - rq * x000_100_1);
                        const double x000_010_0 = QCy * x000_000_0 + WQy * x000_000_1;
                        const double x000_010_1 = QCy * x000_000_1 + WQy * x000_000_2;
                        const double x000_110_0 = QCx * x000_010_0 + WQx * x000_010_1;
                        const double x000_010_2 = QCy * x000_000_2 + WQy * x000_000_3;
                        const double x000_110_1 = QCx * x000_010_1 + WQx * x000_010_2;
                        const double x000_210_0 = QCx * x000_110_0 + WQx * x000_110_1 + 1 * h2q * (x000_010_0 - rq * x000_010_1);
                        const double x000_001_0 = QCz * x000_000_0 + WQz * x000_000_1;
                        const double x000_001_1 = QCz * x000_000_1 + WQz * x000_000_2;
                        const double x000_101_0 = QCx * x000_001_0 + WQx * x000_001_1;
                        const double x000_001_2 = QCz * x000_000_2 + WQz * x000_000_3;
                        const double x000_101_1 = QCx * x000_001_1 + WQx * x000_001_2;
                        const double x000_201_0 = QCx * x000_101_0 + WQx * x000_101_1 + 1 * h2q * (x000_001_0 - rq * x000_001_1);
                        const double x000_020_0 = QCy * x000_010_0 + WQy * x000_010_1 + 1 * h2q * (x000_000_0 - rq * x000_000_1);
                        const double x000_020_1 = QCy * x000_010_1 + WQy * x000_010_2 + 1 * h2q * (x000_000_1 - rq * x000_000_2);
                        const double x000_120_0 = QCx * x000_020_0 + WQx * x000_020_1;
                        const double x000_011_0 = QCy * x000_001_0 + WQy * x000_001_1;
                        const double x000_011_1 = QCy * x000_001_1 + WQy * x000_001_2;
                        const double x000_111_0 = QCx * x000_011_0 + WQx * x000_011_1;
                        const double x000_002_0 = QCz * x000_001_0 + WQz * x000_001_1 + 1 * h2q * (x000_000_0 - rq * x000_000_1);
                        const double x000_002_1 = QCz * x000_001_1 + WQz * x000_001_2 + 1 * h2q * (x000_000_1 - rq * x000_000_2);
                        const double x000_102_0 = QCx * x000_002_0 + WQx * x000_002_1;
                        const double x000_030_0 = QCy * x000_020_0 + WQy * x000_020_1 + 2 * h2q * (x000_010_0 - rq * x000_010_1);
                        const double x000_021_0 = QCy * x000_011_0 + WQy * x000_011_1 + 1 * h2q * (x000_001_0 - rq * x000_001_1);
                        const double x000_012_0 = QCy * x000_002_0 + WQy * x000_002_1;
                        const double x000_003_0 = QCz * x000_002_0 + WQz * x000_002_1 + 2 * h2q * (x000_001_0 - rq * x000_001_1);
                        v[0 * nb + b] = g * x000_300_0;
                        v[1 * nb + b] = g * x000_210_0;
                        v[2 * nb + b] = g * x000_201_0;
                        v[3 * nb + b] = g * x000_120_0;
                        v[4 * nb + b] = g * x000_111_0;
                        v[5 * nb + b] = g * x000_102_0;
                        v[6 * nb + b] = g * x000_030_0;
                        v[7 * nb + b] = g * x000_021_0;
                        v[8 * nb + b] = g * x000_012_0;
                        v[9 * nb + b] = g * x000_003_0;
                }
                for (cb = 0; cb < ncb; cb++) {
                        const double *c = B->c + (size_t)cb * B->ld;
                        for (i = 0; i < 10; i++) {
                                const double *vi = v + (size_t)i * nb;
                                double y = 0;
                                for (b = 0; b < nbt; b++) y += c[b] * vi[b];
                                w[cb * 10 + i] = y;
                        }
                }
                const double kq = K->kp[t];
                for (kc = 0; kc < nck; kc++) {
                        const double f = K->c[(size_t)kc * K->ld + t] * kq;
                        double *so = SK + (size_t)kc * ncb * 10;
                        for (i = 0; i < ncb * 10; i++) so[i] += f * w[i];
                }
        }
        if (!any) return 0;
        double AB[3], CD[3];
        for (i = 0; i < 3; i++) {
                AB[i] = bs ? -B->rij[i] : B->rij[i];
                CD[i] = ks ? -K->rij[i] : K->rij[i];
        }
        (void)AB; (void)CD;
        int ci, cj, ck, cl;
        for (cl = 0; cl < K->ncj; cl++)
        for (ck = 0; ck < K->nci; ck++)
        for (cj = 0; cj < B->ncj; cj++)
        for (ci = 0; ci < B->nci; ci++) {
                const int cpos[4] = {ci, cj, ck, cl};
                const double *sk = SK + ((size_t)(cl * K->nci + ck) * ncb + cj * B->nci + ci) * 10;
                double *o = out + cpos[pos[0]] * 1 * st[0] + cpos[pos[1]] * 1 * st[1]
                          + cpos[pos[2]] * 7 * st[2] + cpos[pos[3]] * 1 * st[3];
                const double *HB = sk;
                double R[10];
                for (i = 0; i < 1; i++) {
                        R[0 + i] = HB[i * 10 + 0];
                        R[1 + i] = HB[i * 10 + 1];
                        R[2 + i] = HB[i * 10 + 2];
                        R[3 + i] = HB[i * 10 + 3];
                        R[4 + i] = HB[i * 10 + 4];
                        R[5 + i] = HB[i * 10 + 5];
                        R[6 + i] = HB[i * 10 + 6];
                        R[7 + i] = HB[i * 10 + 7];
                        R[8 + i] = HB[i * 10 + 8];
                        R[9 + i] = HB[i * 10 + 9];
                }
                o[0 * st[0] + 0 * st[1] + 0 * st[2] + 0 * st[3]] = fac * (1.77013076977993045 * R[1] + -0.590043589926643519 * R[6]);
                o[0 * st[0] + 0 * st[1] + 1 * st[2] + 0 * st[3]] = fac * (2.89061144264055425 * R[4]);
                o[0 * st[0] + 0 * st[1] + 2 * st[2] + 0 * st[3]] = fac * (-0.457045799464465718 * R[1] + -0.457045799464465718 * R[6] + 1.82818319785786287 * R[8]);
                o[0 * st[0] + 0 * st[1] + 3 * st[2] + 0 * st[3]] = fac * (-1.1195289977703462 * R[2] + -1.1195289977703462 * R[7] + 0.746352665180230801 * R[9]);
                o[0 * st[0] + 0 * st[1] + 4 * st[2] + 0 * st[3]] = fac * (-0.457045799464465718 * R[0] + -0.457045799464465718 * R[3] + 1.82818319785786287 * R[5]);
                o[0 * st[0] + 0 * st[1] + 5 * st[2] + 0 * st[3]] = fac * (1.44530572132027713 * R[2] + -1.44530572132027713 * R[7]);
                o[0 * st[0] + 0 * st[1] + 6 * st[2] + 0 * st[3]] = fac * (0.590043589926643519 * R[0] + -1.77013076977993045 * R[3]);
        }
        return 1;
}
